
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_mpwb1k_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_mpwb1k", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.478643817541528e+00, -2.432475152905466e+00, -2.367812753989909e+00, -2.278303903259788e+00, -2.156470888154349e+00, -1.994596044181271e+00, -1.786797681003489e+00, -1.532706350936691e+00, -1.242150358780801e+00, -9.367202767635602e-01, -6.399345293172594e-01, -4.524512270323472e-01, -3.758496113543321e-01, -3.064101528383827e-01, -2.228914434143832e-01, -1.427292851545269e-01, -8.160876002462097e-02, -2.759632594023311e-02, -7.059967387608303e-04, -1.763339089175779e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


